"""
License & HWID Security Manager for SOUMOJIT Hark Automation
Implements:
1. Hardware Fingerprinting (HWID Lock - Motherboard UUID + Machine GUID + CPU)
2. HMAC-SHA256 Cryptographic License Generation and Local Validation
3. Expiry date enforcement (Days, Expiry timestamp)
4. Local secure storage of license token
"""

import os
import sys
import hmac
import hashlib
import json
import base64
import subprocess
from datetime import datetime, timedelta

# Master Secret Key known only to SOUMOJIT software core
# Used to verify that license keys were generated by the authentic admin keygen
MASTER_SECRET = b"SOUMOJIT_HARK_MASTER_SECURITY_KEY_2026_@#$!*&^%"

def get_base_dir():
    if getattr(sys, 'frozen', False):
        return os.path.dirname(sys.executable)
    return os.path.dirname(os.path.abspath(__file__))

LICENSE_FILE = os.path.join(get_base_dir(), "license.key")

def get_machine_hwid() -> str:
    """
    Extracts 100% stable, permanent hardware identifiers:
    Windows MachineGuid (unique per Windows installation) + CPU Processor Identifier.
    Zero-delay, zero-permission requirement, permanent across all reboots.
    """
    import winreg
    guid_val = ""
    try:
        key = winreg.OpenKey(
            winreg.HKEY_LOCAL_MACHINE,
            r"SOFTWARE\Microsoft\Cryptography",
            0,
            winreg.KEY_READ | winreg.KEY_WOW64_64KEY
        )
        guid_val, _ = winreg.QueryValueEx(key, "MachineGuid")
        winreg.CloseKey(key)
    except Exception:
        pass

    cpu_id = os.environ.get("PROCESSOR_IDENTIFIER", "GENERIC_X64_CPU")
    comp_name = os.environ.get("COMPUTERNAME", "PC")

    combined = f"{guid_val}||{cpu_id}||{comp_name}".upper()
    h = hashlib.sha256(combined.encode("utf-8")).hexdigest().upper()
    return f"{h[0:4]}-{h[4:8]}-{h[8:12]}-{h[12:16]}"

def create_license_payload(client_name: str, hwid: str, days: int = 30) -> str:
    """
    ADMIN FUNCTION: Generates an encrypted/signed license key string.
    days=0 or days>3650 represents LIFETIME access.
    """
    hwid_clean = hwid.strip().upper()
    if days <= 0 or days > 3650:
        exp_str = "LIFETIME"
    else:
        exp_date = datetime.now() + timedelta(days=days)
        exp_str = exp_date.strftime("%Y-%m-%d")

    payload = {
        "client": client_name.strip(),
        "hwid": hwid_clean,
        "exp": exp_str,
        "created": datetime.now().strftime("%Y-%m-%d")
    }

    payload_json = json.dumps(payload, sort_keys=True)
    payload_b64 = base64.b64encode(payload_json.encode("utf-8")).decode("utf-8")

    # Generate HMAC Signature using MASTER_SECRET
    sig = hmac.new(MASTER_SECRET, payload_b64.encode("utf-8"), hashlib.sha256).hexdigest()[:16].upper()

    # Formatted Key: SJHK-<PAYLOAD_B64>-<SIG>
    return f"SJHK.{payload_b64}.{sig}"

def verify_license_key(license_str: str) -> dict:
    """
    Validates a license key:
    1. Checks HMAC signature against MASTER_SECRET.
    2. Checks Hardware ID (HWID) match with the running machine.
    3. Checks expiry date.
    Returns: {"valid": bool, "reason": str, "client": str, "expires": str, "days_left": int}
    """
    if not license_str or not isinstance(license_str, str):
        return {"valid": False, "reason": "No license key provided"}

    license_str = license_str.strip()
    parts = license_str.split(".")
    if len(parts) != 3 or parts[0] != "SJHK":
        return {"valid": False, "reason": "Invalid license key format"}

    payload_b64 = parts[1]
    sig_provided = parts[2].upper()

    # Verify HMAC
    expected_sig = hmac.new(MASTER_SECRET, payload_b64.encode("utf-8"), hashlib.sha256).hexdigest()[:16].upper()
    if not hmac.compare_digest(sig_provided, expected_sig):
        return {"valid": False, "reason": "Tampered or counterfeit license key"}

    # Decode Payload
    try:
        payload_json = base64.b64decode(payload_b64.encode("utf-8")).decode("utf-8")
        data = json.loads(payload_json)
    except Exception:
        return {"valid": False, "reason": "Corrupted license data"}

    # 1. Verify HWID
    current_hwid = get_machine_hwid()
    expected_hwid = data.get("hwid", "").strip().upper()
    if expected_hwid != current_hwid:
        return {
            "valid": False,
            "reason": f"Device HWID mismatch!\nThis key belongs to another PC:\n{expected_hwid}\nYour PC HWID:\n{current_hwid}",
            "client": data.get("client", "Unknown"),
            "current_hwid": current_hwid
        }

    # 2. Verify Expiry
    exp_str = data.get("exp", "EXPIRED")
    client = data.get("client", "Valued Customer")

    if exp_str == "LIFETIME":
        return {
            "valid": True,
            "reason": "Lifetime VIP License",
            "client": client,
            "expires": "LIFETIME (Permanent)",
            "days_left": 99999
        }

    try:
        exp_date = datetime.strptime(exp_str, "%Y-%m-%d")
        now = datetime.now()
        if now > exp_date + timedelta(days=1):
            return {
                "valid": False,
                "reason": f"Subscription expired on {exp_str}. Please contact admin to renew.",
                "client": client,
                "expires": exp_str,
                "days_left": 0
            }
        
        days_left = max(0, (exp_date - now).days + 1)
        return {
            "valid": True,
            "reason": f"Active ({days_left} days remaining)",
            "client": client,
            "expires": exp_str,
            "days_left": days_left
        }
    except Exception:
        return {"valid": False, "reason": "Invalid expiration timestamp in license"}

def save_license(license_str: str) -> bool:
    try:
        with open(LICENSE_FILE, "w", encoding="utf-8") as f:
            f.write(license_str.strip())
        return True
    except Exception:
        return False

def load_saved_license() -> str:
    if os.path.exists(LICENSE_FILE):
        try:
            with open(LICENSE_FILE, "r", encoding="utf-8") as f:
                return f.read().strip()
        except Exception:
            return ""
    return ""

def check_system_license() -> dict:
    saved = load_saved_license()
    if not saved:
        return {
            "valid": False,
            "reason": "No license activated on this PC.",
            "current_hwid": get_machine_hwid()
        }
    res = verify_license_key(saved)
    res["current_hwid"] = get_machine_hwid()
    return res

